insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_59_v1'
from (values
('127.397.d.1.A',3,'A student notices a hinge on a lab cart squeaks and binds. Which question best defines an engineering problem?','["How can the hinge be redesigned to move smoothly?", "Who bought the cart?", "How old is the hinge?", "What color is the cart?"]'::jsonb,0,'A defined problem asks how to improve a specific function.','original'),
('127.397.d.1.A',4,'Observations show a wind turbine model stalls at low speeds. Which is the best testable question?','["Who invented wind?", "Does blade pitch change the starting speed?", "Why do people like turbines?", "Is wind pretty?"]'::jsonb,1,'Testable questions name a variable and an outcome.','original'),
('127.397.d.1.B',3,'To compare three bridge deck designs fairly, a team should change:','["the loads each time", "every material at once", "only the deck design", "the testing day and team"]'::jsonb,2,'A comparative test changes one variable.','original'),
('127.397.d.1.B',4,'A descriptive investigation of a truss would mostly involve:','["skipping measurements", "guessing its strength", "changing three materials at once", "recording observations of how it behaves under load"]'::jsonb,3,'Descriptive work records what happens.','original'),
('127.397.d.1.C',3,'Before cutting metal in the engineering lab, a student must wear:','["safety glasses and follow the shop rules", "sandals and a scarf", "nothing special", "headphones only"]'::jsonb,0,'Eye protection and rules prevent injury.','original'),
('127.397.d.1.C',4,'A fire extinguisher in a lab should be:','["used as a doorstop", "accessible and inspected on a schedule", "hidden in a closet", "locked away"]'::jsonb,1,'Safety equipment must be reachable and maintained.','original'),
('127.397.d.1.D',3,'Which tool measures the outside diameter of a small shaft to a thousandth of an inch?','["protractor only", "bathroom scale", "micrometer", "yardstick"]'::jsonb,2,'Micrometers measure to 0.001 inch.','original'),
('127.397.d.1.D',4,'A student needs to measure an angle on a bracket. The best tool is a:','["caliper depth rod", "thermometer", "stopwatch", "protractor"]'::jsonb,3,'Protractors measure angles.','original'),
('127.397.d.1.E',3,'In the International System of Units, force is measured in:','["newtons", "feet", "gallons", "pounds"]'::jsonb,0,'The SI unit of force is the newton.','original'),
('127.397.d.1.E',4,'Recording a beam length as 2,500 millimeters is the same as:','["25 meters", "2.5 meters", "250 meters", "0.25 meters"]'::jsonb,1,'1,000 mm = 1 m.','original'),
('127.397.d.1.F',3,'To graph load versus deflection for a beam test, a student would organize the data in a:','["recipe", "sandbox", "spreadsheet", "calendar page"]'::jsonb,2,'Spreadsheets organize and graph data.','original'),
('127.397.d.1.F',4,'Qualitative notes in an engineering notebook might include:','["only numbers", "blank pages", "nothing", "observations of how a joint cracked"]'::jsonb,3,'Qualitative data describes characteristics.','original'),
('127.397.d.1.G',3,'A scale model of a bridge is useful because it lets engineers:','["test ideas before building the full-size structure", "avoid the design", "remove the load", "skip all testing"]'::jsonb,0,'Models allow low-cost testing.','original'),
('127.397.d.1.G',4,'A computer simulation of airflow over a wing is an example of a:','["physical toy only", "mathematical or computational model", "report card", "guess"]'::jsonb,1,'Simulations model systems with equations.','original'),
('127.397.d.1.H',3,'A scientific theory differs from a hypothesis because a theory:','["is a wild guess", "is always a law", "is supported by a large body of evidence", "has no tests"]'::jsonb,2,'Theories are well tested.','original'),
('127.397.d.1.H',4,'A scientific law usually describes:','["a company rule", "why a person likes music", "an opinion", "what happens in nature, often with a mathematical statement"]'::jsonb,3,'Laws describe observed regularities.','original'),
('127.397.d.2.A',3,'A limitation of a small-scale bridge model is that it may not show:','["how the full-size materials will behave", "the bridge''s existence", "its color", "any shape"]'::jsonb,0,'Scale affects material behavior.','original'),
('127.397.d.2.A',4,'Using a larger-scale model generally allows an engineer to:','["avoid costs", "observe more detail but at higher cost", "remove all limits", "hide errors"]'::jsonb,1,'Larger models show detail and cost more.','original'),
('127.397.d.2.B',3,'A group of test strengths clusters near 500 pounds, with one result at 900. The 900 is called a(n):','["median", "unit", "outlier", "constant"]'::jsonb,2,'An outlier lies far from the pattern.','original'),
('127.397.d.2.B',4,'Plotting load against time and seeing a straight upward line suggests a:','["random pattern", "stopped test", "flat result", "steady rate of change"]'::jsonb,3,'A straight rising line means constant rate.','original'),
('127.397.d.2.C',3,'A spring stretches 2 centimeters under 4 newtons. Assuming a linear spring, 8 newtons stretches it:','["4 centimeters", "1 centimeter", "16 centimeters", "2 centimeters"]'::jsonb,0,'Stretch is proportional to force.','original'),
('127.397.d.2.C',4,'A beam carries 300 newtons over an area of 0.5 square meters. The pressure is:','["0.0017 pascals", "600 pascals", "150 pascals", "300 pascals"]'::jsonb,1,'300 / 0.5 = 600.','original'),
('127.397.d.2.D',3,'To evaluate an engineering design, a team compares test results with the:','["team shirts", "lunch menu", "original design requirements", "school colors"]'::jsonb,2,'Evaluation checks requirements.','original'),
('127.397.d.2.D',4,'An experiment is flawed if it has no way to measure:','["the team name", "the room number", "the date", "the effect of the changed variable"]'::jsonb,3,'The outcome must be measurable.','original'),
('127.397.d.3.A',3,'A recommendation to use steel instead of plastic for a bracket is strongest when supported by:','["strength test data", "popularity", "price tags only", "opinion only"]'::jsonb,0,'Data supports a recommendation.','original'),
('127.397.d.3.A',4,'A proposed solution should address the original:','["weather", "problem statement and constraints", "team schedule only", "fashion trends"]'::jsonb,1,'Solutions answer the defined problem.','original'),
('127.397.d.3.B',3,'When a team explains a design to others, the explanation should include:','["no visuals", "guesses only", "evidence and clear reasoning", "unrelated stories"]'::jsonb,2,'Communication needs evidence.','original'),
('127.397.d.3.B',4,'Working collaboratively on a design report means each member:','["writes alone", "copies work", "avoids reviewing", "contributes sections and reviews others"]'::jsonb,3,'Collaboration shares work.','original'),
('127.397.d.3.C',3,'In a respectful scientific argument, disagreements are settled by:','["evidence and logic", "rank", "teasing", "volume"]'::jsonb,0,'Arguments rest on evidence.','original'),
('127.397.d.3.C',4,'When a teammate''s data contradicts yours, a respectful response is to:','["argue louder", "review both methods to find the cause", "hide your data", "dismiss it"]'::jsonb,1,'Check the methods.','original'),
('127.397.d.4.A',3,'Critiquing a classmate''s solution should focus on:','["personal traits", "accents", "the evidence and reasoning", "their shoes"]'::jsonb,2,'Critique the work, not the person.','original'),
('127.397.d.4.A',4,'An explanation is weakened when it relies on:','["repeated trials", "calibrated tools", "clear data", "a single unrepeated result"]'::jsonb,3,'Repeatability strengthens claims.','original'),
('127.397.d.4.B',3,'Discoveries in materials science, such as stronger alloys, have changed:','["how buildings and bridges are designed", "nothing at all", "only art", "only weather"]'::jsonb,0,'Research shapes engineering practice.','original'),
('127.397.d.4.B',4,'Past failures such as bridge collapses have led engineers to:','["ignore standards", "revise codes and safety margins", "lower safety", "stop building"]'::jsonb,1,'Failures drive improvements.','original'),
('127.397.d.4.C',3,'To learn about engineering careers, a student could visit a:','["empty lot", "costume shop", "professional engineering society or industry site", "random vending machine"]'::jsonb,2,'Societies provide career information.','original'),
('127.397.d.4.C',4,'Which resource is most reliable for the properties of a steel alloy?','["a poster", "an anonymous comment", "a rumor", "a published engineering handbook"]'::jsonb,3,'Handbooks are vetted references.','original'),
('127.397.d.5.A',3,'Compared with an engineer, an engineering technologist usually works more on:','["applying and implementing existing designs", "inventing new theory", "accounting", "law"]'::jsonb,0,'Technology focuses on application.','original'),
('127.397.d.5.A',4,'A key difference between engineering and engineering technology is that engineering emphasizes:','["only repair", "theory, analysis, and original design", "only sales", "only filing"]'::jsonb,1,'Engineers use more theory and math.','original'),
('127.397.d.5.B',3,'A job that uses CAD to draw parts for production is that of a:','["pilot", "lifeguard", "drafter or design technician", "florist"]'::jsonb,2,'Drafters create technical drawings.','original'),
('127.397.d.5.B',4,'A quality technician''s role typically includes:','["teaching dance", "writing songs", "selling cars", "inspecting parts against specifications"]'::jsonb,3,'Quality techs inspect.','original'),
('127.397.d.5.C',3,'The engineering discipline that designs power systems and circuits is:','["electrical engineering", "civil engineering", "mining engineering", "chemical engineering"]'::jsonb,0,'Electrical engineers handle circuits and power.','original'),
('127.397.d.5.C',4,'Designing roads, bridges, and water systems belongs to:','["aerospace engineering", "civil engineering", "biomedical engineering", "software engineering"]'::jsonb,1,'Civil engineering covers infrastructure.','original'),
('127.397.d.5.D',3,'A technical drawing should be accompanied by a written:','["joke", "recipe", "description with specifications", "menu"]'::jsonb,2,'Specifications explain the drawing.','original'),
('127.397.d.5.D',4,'An engineer presenting to a non-technical audience should:','["speak quickly", "use only jargon", "avoid questions", "use plain language and visuals"]'::jsonb,3,'Adapt to the audience.','original'),
('127.397.d.6.A',3,'On a team design problem, dividing tasks by member strengths helps the team:','["finish more efficiently", "create conflict", "avoid work", "miss deadlines"]'::jsonb,0,'Strength-based roles improve efficiency.','original'),
('127.397.d.6.A',4,'When solving a design problem alone, the first step is to:','["paint it", "define the problem clearly", "build immediately", "order materials"]'::jsonb,1,'Define before design.','original'),
('127.397.d.6.B',3,'Creating a solution with a design process means moving through steps such as:','["draw, hide, quit", "sleep, eat, run", "define, brainstorm, build, test, improve", "buy, sell, lose"]'::jsonb,2,'The process is iterative.','original'),
('127.397.d.6.B',4,'If a prototype fails testing, the design process suggests you:','["stop forever", "declare success", "blame the clock", "redesign and test again"]'::jsonb,3,'Iteration follows failure.','original'),
('127.397.d.6.C',3,'A design brief lists the problem, constraints, and:','["criteria for success", "gossip", "birthdays", "jokes"]'::jsonb,0,'Briefs state success criteria.','original'),
('127.397.d.6.C',4,'A constraint in a design brief might be:','["no rules", "a maximum cost of $50", "an unlimited budget", "a wish"]'::jsonb,1,'Constraints limit options.','original'),
('127.397.d.6.D',3,'Good team communication includes:','["ignoring teammates", "secret plans", "active listening and clear updates", "interrupting"]'::jsonb,2,'Listening and updating keep teams aligned.','original'),
('127.397.d.6.D',4,'A team agrees on a weekly status check so that members:','["work alone", "avoid work", "hide delays", "stay informed about progress and problems"]'::jsonb,3,'Status checks improve awareness.','original'),
('127.397.d.6.E',3,'Researching existing solutions before designing helps a team avoid:','["reinventing solutions that already exist", "testing", "learning", "teamwork"]'::jsonb,0,'Research informs design.','original'),
('127.397.d.6.E',4,'Team research is most useful when members:','["copy without credit", "share and organize their findings", "keep findings private", "skip sources"]'::jsonb,1,'Shared research builds knowledge.','original'),
('127.397.d.7.A',3,'In a bicycle drivetrain, the chain connects two toothed wheels called:','["cams only", "bearings", "sprockets", "magnets"]'::jsonb,2,'Sprockets mesh with a chain to transmit motion.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
