insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_59_v1'
from (values
('127.398.d.4.A',3,'In a right triangle, the sine of an angle equals the opposite side divided by the:','["hypotenuse", "adjacent side", "perimeter", "angle"]'::jsonb,0,'SOH.','original'),
('127.398.d.4.A',4,'A right triangle has an angle whose opposite side is 3 and adjacent side is 4. The tangent of the angle is:','["5", "0.75", "1.33", "0.6"]'::jsonb,1,'3 / 4.','original'),
('127.398.d.4.B',3,'A surveyor stands 20 meters from a tower and sights its top at 60 degrees above level. The tower''s height is about:','["11.5 meters", "20 meters", "34.6 meters", "40 meters"]'::jsonb,2,'20 x tan 60 = 34.6.','original'),
('127.398.d.4.B',4,'A technician stands 20 meters from a pole and measures a 30 degree angle to its top. The pole is about:','["34.6 meters", "20 meters", "10 meters", "11.5 meters"]'::jsonb,3,'20 x tan 30 = 11.5.','original'),
('127.398.d.5.A',3,'A drawing is scaled 1 to 4 (drawing to real). A feature measures 3 inches on the drawing. The real feature is:','["12 inches", "7 inches", "0.75 inches", "1 inch"]'::jsonb,0,'3 x 4 = 12.','original'),
('127.398.d.5.A',4,'A bracket is 20 centimeters long and is drawn at half size. On the drawing it measures:','["20 centimeters", "10 centimeters", "5 centimeters", "40 centimeters"]'::jsonb,1,'Half of 20.','original'),
('127.398.d.5.B',3,'If a machine finishes 30 parts in one hour, its production rate is:','["60 parts", "30 hours", "30 parts per hour", "2 hours per part"]'::jsonb,2,'Rate is output per time.','original'),
('127.398.d.5.B',4,'Production time is the time to make one unit, while production rate is the number of units made per:','["volt", "color", "pound", "unit of time"]'::jsonb,3,'Rate = units / time.','original'),
('127.398.d.5.C',3,'A machine finishes one part every 40 seconds. In 1 hour it makes:','["90 parts", "60 parts", "40 parts", "144 parts"]'::jsonb,0,'3,600 / 40 = 90.','original'),
('127.398.d.5.C',4,'If cycle time is reduced from 50 seconds to 40 seconds, hourly output rises from 72 parts to:','["60 parts", "90 parts", "80 parts", "100 parts"]'::jsonb,1,'3,600 / 40 = 90.','original'),
('127.398.d.5.D',3,'A 4 to 1 reduction gear set has an input speed of 1,200 revolutions per minute. The output speed is:','["1,204 revolutions per minute", "1,196 revolutions per minute", "300 revolutions per minute", "4,800 revolutions per minute"]'::jsonb,2,'1,200 / 4.','original'),
('127.398.d.5.D',4,'An ideal gear reduction of 4 to 1 turns 10 newton-meters of input torque into:','["6 newton-meters", "2.5 newton-meters", "14 newton-meters", "40 newton-meters"]'::jsonb,3,'Torque multiplies by the ratio.','original'),
('127.398.d.5.E',3,'In a simple gear train, an odd number of gears (such as 3) makes the output turn:','["in the same direction as the input", "at random", "not at all", "in the opposite direction"]'::jsonb,0,'Each mesh reverses direction.','original'),
('127.398.d.5.E',4,'A two-gear train has an output that turns:','["never", "opposite to the input", "with the input", "twice as fast always"]'::jsonb,1,'One mesh reverses the direction.','original'),
('127.398.d.5.F',3,'To make an output slower but stronger than the input, the driving gear should be:','["larger than the driven gear", "the same size always", "smaller than the driven gear", "removed"]'::jsonb,2,'A smaller driver turning a larger gear reduces speed.','original'),
('127.398.d.5.F',4,'A motor turns at 1,800 revolutions per minute and the load needs 600. The gear ratio must be:','["1 to 3", "6 to 1", "2 to 1", "3 to 1"]'::jsonb,3,'1,800 / 600 = 3.','original'),
('127.398.d.5.G',3,'Spur gears of 20 and 40 teeth with a diametral pitch of 10 have a center distance of:','["3 inches", "1.5 inches", "30 inches", "6 inches"]'::jsonb,0,'(20 + 40) / (2 x 10) = 3.','original'),
('127.398.d.5.G',4,'If two meshing gears are placed too far apart, they will:','["mesh better", "fail to mesh properly", "last longer", "run quieter"]'::jsonb,1,'Center distance must fit the gear teeth.','original'),
('127.398.d.5.H',3,'A hole positioned at 2.000 inches with a tolerance of plus or minus 0.005 inch may measure as much as:','["2.500 inches", "2.050 inches", "2.005 inches", "1.995 only"]'::jsonb,2,'Upper limit is 2.000 + 0.005.','original'),
('127.398.d.5.H',4,'Stacking tolerances of several parts in an assembly can cause the total error to:','["vanish", "reverse", "cancel always", "add up"]'::jsonb,3,'Tolerances accumulate.','original'),
('127.398.d.5.I',3,'A part costs $2 in material and $3 in labor. The cost of 100 parts is:','["$500", "$5", "$300", "$200"]'::jsonb,0,'$5 x 100.','original'),
('127.398.d.5.I',4,'A machine costs $60 per hour to run and makes 120 parts per hour. The machine cost per part is:','["$2.00", "$0.50", "$60.00", "$7,200"]'::jsonb,1,'60 / 120.','original'),
('127.398.d.5.J',3,'For a milling cutter, a higher cutting speed with the same diameter requires a higher:','["tool color", "feed table", "spindle speed", "part number"]'::jsonb,2,'RPM scales with surface speed.','original'),
('127.398.d.5.J',4,'Using RPM = 4 x cutting speed / diameter, a 2-inch cutter at 100 feet per minute should spin at:','["800 revolutions per minute", "50 revolutions per minute", "20 revolutions per minute", "200 revolutions per minute"]'::jsonb,3,'4 x 100 / 2.','original'),
('127.398.d.5.K',3,'A two-flute cutter turns at 400 RPM with a chip load of 0.005 inch per tooth. The feed rate is:','["4 inches per minute", "2 inches per minute", "40 inches per minute", "0.4 inches per minute"]'::jsonb,0,'400 x 2 x 0.005 = 4.','original'),
('127.398.d.5.K',4,'Increasing the feed rate while keeping the speed the same increases the:','["spindle speed", "chip load", "tool color", "part number"]'::jsonb,1,'More feed per revolution means more chip load.','original'),
('127.398.d.5.L',3,'In an injection mold, a longer runner generally causes a:','["pressure gain", "zero pressure drop", "larger pressure drop", "smaller pressure drop"]'::jsonb,2,'Longer flow path means more resistance.','original'),
('127.398.d.5.L',4,'Thicker, hotter plastic flowing through a narrow passage makes the pressure needed to fill the mold:','["unchanged always", "lower", "zero", "higher"]'::jsonb,3,'Narrow flow paths and viscosity raise pressure.','original'),
('127.398.d.5.M',3,'A gate that is too small in an injection mold can cause:','["incomplete filling or high shear", "faster cooling always", "perfect parts", "lower pressure"]'::jsonb,0,'Small gates restrict flow.','original'),
('127.398.d.5.M',4,'A gate that is too large can leave:','["no mark", "a large mark that is hard to trim", "an empty mold", "a weaker part always"]'::jsonb,1,'Large gates leave visible vestiges.','original'),
('127.398.d.5.N',3,'The overall mold block size must be large enough to hold the cavity, the runners, and the:','["paperwork", "trucks", "cooling channels and walls", "workers"]'::jsonb,2,'Mold size includes support features.','original'),
('127.398.d.5.N',4,'A mold with more cavities generally needs a mold block that is:','["invisible", "the same", "smaller", "larger"]'::jsonb,3,'More cavities need more space.','original'),
('127.398.d.5.O',3,'In a multi-cavity mold, balanced runners are designed so each cavity:','["fills at the same time", "stays empty", "fills from the cavity next door", "fills last"]'::jsonb,0,'Balance gives uniform parts.','original'),
('127.398.d.5.O',4,'If runners to some cavities are longer than others, the parts from those cavities are likely to be:','["identical", "underfilled or different in quality", "stronger", "cheaper"]'::jsonb,1,'Unbalanced runners cause variation.','original'),
('127.398.d.6.A',3,'Using Ohm''s law, a circuit with 24 volts across 8 ohms has a current of:','["32 amperes", "192 amperes", "3 amperes", "0.33 amperes"]'::jsonb,2,'I = V / R.','original'),
('127.398.d.6.A',4,'The power in a circuit with 5 amperes through 10 ohms is:','["15 watts", "2 watts", "50 watts", "250 watts"]'::jsonb,3,'P = I squared x R = 25 x 10.','original'),
('127.398.d.6.B',3,'A resistor of 4,700 ohms is written in engineering notation as:','["4.7 kilohms", "4.7 megohms", "0.47 kilohms", "47 kilohms"]'::jsonb,0,'4,700 = 4.7 x 10^3.','original'),
('127.398.d.6.B',4,'A current of 0.0033 amperes is written in engineering notation as:','["0.33 milliamperes", "3.3 milliamperes", "33 milliamperes", "3.3 microamperes"]'::jsonb,1,'10^-3 is milli.','original'),
('127.398.d.6.C',3,'Direct current flows in one direction, while alternating current:','["stops at zero forever", "flows in one direction only", "reverses direction periodically", "never flows"]'::jsonb,2,'AC alternates.','original'),
('127.398.d.6.C',4,'A 60 hertz alternating current completes how many cycles each second?','["6", "600", "1", "60"]'::jsonb,3,'Hertz means cycles per second.','original'),
('127.398.d.6.D',3,'An inductor in an AC circuit opposes changes in:','["current", "resistor values only", "color", "mass"]'::jsonb,0,'Inductors resist current change.','original'),
('127.398.d.6.D',4,'As the frequency of an AC signal rises, the opposition of an inductor:','["reverses", "increases", "stays zero", "decreases"]'::jsonb,1,'Inductive reactance rises with frequency.','original'),
('127.398.d.6.E',3,'A capacitor in an AC circuit passes alternating current but blocks:','["all signals", "nothing", "steady direct current", "alternating current"]'::jsonb,2,'Capacitors block DC after charging.','original'),
('127.398.d.6.E',4,'As the frequency of an AC signal rises, the opposition of a capacitor:','["stays infinite", "increases", "reverses", "decreases"]'::jsonb,3,'Capacitive reactance falls with frequency.','original'),
('127.398.d.6.F',3,'The time constant of an RC circuit is found by multiplying resistance by:','["capacitance", "voltage", "current", "power"]'::jsonb,0,'Tau = R x C.','original'),
('127.398.d.6.F',4,'A 10-kilohm resistor with a 100-microfarad capacitor gives a time constant of:','["1,000 seconds", "1 second", "10 seconds", "0.1 seconds"]'::jsonb,1,'10,000 x 0.0001 = 1.','original'),
('127.398.d.6.G',3,'A transformer with a 10 to 1 turns ratio steps 120 volts down to:','["130 volts", "110 volts", "12 volts", "1,200 volts"]'::jsonb,2,'120 / 10.','original'),
('127.398.d.6.G',4,'An ideal transformer steps voltage down by a factor of 10. The current on the secondary side is:','["unchanged", "zero", "10 times smaller", "10 times larger"]'::jsonb,3,'Power in equals power out.','original'),
('127.398.d.6.H',3,'The RMS value of an AC voltage with a 170-volt peak is about:','["120 volts", "85 volts", "170 volts", "240 volts"]'::jsonb,0,'170 / 1.414 = 120.','original'),
('127.398.d.6.H',4,'RMS voltage is useful because it equals the DC voltage that would deliver the same:','["color", "heating power", "weight", "frequency"]'::jsonb,1,'RMS matches DC power.','original'),
('127.398.d.6.I',3,'A 1-kilowatt motor runs for 8 hours. The energy used is:','["9 kilowatt-hours", "1 kilowatt-hour", "8 kilowatt-hours", "0.125 kilowatt-hours"]'::jsonb,2,'1 x 8.','original'),
('127.398.d.6.I',4,'Electricity costs $0.12 per kilowatt-hour. A 2-kilowatt motor running 5 hours costs:','["$0.60", "$0.24", "$10.00", "$1.20"]'::jsonb,3,'2 x 5 x 0.12.','original'),
('127.398.d.7.A',3,'A cylinder extends with 1,000 psi acting on a 4-square-inch piston face. The extension force is:','["4,000 pounds", "996 pounds", "1,004 pounds", "250 pounds"]'::jsonb,0,'F = P x A.','original'),
('127.398.d.7.A',4,'On the retraction stroke, a cylinder produces less force than on extension because the fluid acts on an area reduced by the:','["cylinder paint", "piston rod", "gauge", "pump label"]'::jsonb,1,'Rod area is subtracted on the rod side.','original'),
('127.398.d.7.B',3,'Absolute pressure is gage pressure plus:','["zero", "flow rate", "atmospheric pressure", "temperature"]'::jsonb,2,'Absolute = gage + atmospheric.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
